//! The checked-in ambient prefix over ds-dsi's artifact format: the
//! embedded `.dsi` (regenerated by the `gen-ambient-dsi` example) and
//! the ambient-specific generation — parse, derive expansion, the
//! declaration-phase snapshot, the clean gate, the effects pass, the
//! method rows — everything else (the payload's shape, the extraction,
//! the decode and serve, the drift-gate views) living in [`ds_dsi`],
//! the format both the ambient and a user package's compile share.

use std::sync::Arc;

use ds_check::{DefId, IdTable, Park};
use ds_dsi::{PrefixDsi, PrefixDsiError, ServedPrefix};
use ds_mod::Hash128;
use ds_parse::LocalDecl;

/// The embedded artifact: source-hash header plus the postcard-encoded
/// tables.
static DSI: &[u8] = include_bytes!("ambient.dsi");

/// The artifact's decoded payload, decoded once per process: the bytes
/// address no caller state, so a process that serves the same ambient
/// repeatedly (a package graph's member compiles, a query session) pays
/// the postcard decode once. A decode failure stays cached with it: a
/// drifted artifact answers every caller with the same miss it answers
/// today, only without re-decoding the bytes per call.
static ARTIFACT: std::sync::OnceLock<Result<PrefixDsi, PrefixDsiError>> =
    std::sync::OnceLock::new();

/// The artifact's converted namespace and declaration tables, converted
/// once per process beside the decode: every serve installs the same
/// shared bases (the package's base tier and the shared resolution
/// tables among them), so a member compile's teardown drops refcounts
/// instead of the rows and a later serve never rebuilds the conversion.
/// A conversion failure stays cached with it, exactly like the decode's.
static TABLES: Park<Result<ds_dsi::ServedTables, PrefixDsiError>> = Park::new();

/// The ambient's shared const rows, built once per process from the
/// resident tree over the served namespace: every bodied fn is a
/// const-of-lambda binding, so the rows carry whole fn bodies and
/// cloning them per member compile dominated the reserve walk's cost
/// and the bundle's teardown. Built from the blob's tree when it
/// verifies; a blob miss leaves the base absent and the reserve walk
/// rebuilds the rows exactly as before (the artifacts are a pure cache,
/// so both miss together in practice).
static CONSTS: Park<Arc<IdTable<DefId, Arc<LocalDecl>>>> = Park::new();

/// The ambient's parked affine walk, the fill-later [`Park`] kind:
/// filled by the first member compile that runs it over the served tree
/// and installed by every later one — the walk's rows name spans and
/// the serve's own definition ids (each serve rebuilds the namespace
/// identically), so one process walks the ambient tree once instead of
/// once per member compile.
static LINEARITY: Park<ds_check::ServedLinearity> = Park::new();

/// The ambient serve's affine-walk park cell: the run path hands it to
/// the checker's served walk, which fills it on the first compile and
/// installs it after.
#[must_use]
pub fn ambient_linearity() -> &'static Park<ds_check::ServedLinearity> {
    &LINEARITY
}

/// Generates the artifact from the current ambient source: parse,
/// derive-expansion, collect and resolve, the declaration phase alone
/// (the mint/set logs snapshot the phase boundary — the body pass
/// interns more sets), then the full analyze for the clean gate, the
/// effects pass, and the method rows — everything a served run must
/// reproduce. The ambient must check clean and resolve clean on its own
/// (the artifact serves a clean generation or nothing).
#[must_use]
pub fn generate() -> PrefixDsi {
    let mut files = ds_diag::Files::new();
    let file = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
    let ast = ds_parse::parse(&files, file).expect("the ambient parses");
    let (expanded, diags) = ds_meta::expand_derives(&[&ast]);
    assert!(diags.is_empty(), "the ambient derives refuse: {diags:?}");
    let tree = expanded.into_iter().next().expect("one");
    let mut package = ds_check::Package::new();
    let mut resolve_diags = package.add_file(&tree);
    let (uses, mut file_diags) = package.resolve(&tree);
    resolve_diags.append(&mut file_diags);
    let tables = vec![uses];
    let (decls, decl_diags) = ds_check::decls::build(&package, &[tree.as_ref()], &tables);
    assert!(
        decl_diags.is_empty(),
        "the ambient does not declare clean: {decl_diags:?}"
    );
    let analyzed = ds_check::analyze_resolved(
        &files,
        Arc::from(vec![tree]),
        package.into(),
        tables.into(),
        resolve_diags,
        Arc::default(),
    );
    assert!(
        analyzed.checked.diags.is_empty(),
        "the ambient does not check clean: {:?}",
        analyzed.checked.diags
    );
    let rows = crate::declared_rows();
    let caps = crate::world_caps();
    let effects = ds_check::effects::effects_of_resolved(
        &analyzed.asts[..],
        &analyzed.package,
        &analyzed.resolutions[..],
        &analyzed.checked.hole_show_dispatches,
        rows,
        caps,
    );
    let method_rows = ds_check::effects::solved_method_rows(
        &analyzed.asts[..],
        &analyzed.package,
        &analyzed.resolutions[..],
        rows,
        caps,
    );
    ds_dsi::extract(&decls, &analyzed, &effects, &method_rows)
}

/// The embedded artifact's serve: the source-hash header must match the
/// current [`AMBIENT_SOURCE`](crate::AMBIENT_SOURCE), the payload must
/// decode, and the decoded tables must address exactly `file` (the id
/// the caller registered the ambient under — the standard
/// first-registered discipline, the same as the AST blob's). Any miss is
/// an error the caller answers with the fresh compute.
///
/// # Errors
///
/// [`PrefixDsiError`]: a stale header, a foreign file id, or a corrupt
/// payload — all of them cache misses, never source problems.
pub fn ambient_dsi(file: ds_diag::FileId) -> Result<ServedPrefix, PrefixDsiError> {
    let artifact = ARTIFACT.get_or_init(|| {
        ds_dsi::decode_prefix(DSI, Hash128::compute(crate::AMBIENT_SOURCE.as_bytes()))
    });
    let artifact = artifact.as_ref().map_err(Clone::clone)?;
    let tables = TABLES.get_or_init(|| ds_dsi::convert_tables(artifact));
    let tables = tables.as_ref().map_err(Clone::clone)?;
    let mut served = ds_dsi::serve_prefix_tables(artifact, &[file], tables)?;
    if let Ok(tree) = crate::ambient_ast(file) {
        let consts = CONSTS.get_or_init(|| ds_check::decls::consts_base(&tree, &served.package));
        served.decls.decls.consts.install_base(Arc::clone(consts));
    }
    Ok(served)
}

#[cfg(test)]
mod tests {
    use ds_dsi::{PrefixDsiError, artifact_bytes, gates};

    use super::DSI;

    /// The artifact's source-hash header.
    const HEADER: usize = 16;

    /// A user file exercising the surface the serve must thread: a
    /// derive (whose synthesized impl the body pass checks against the
    /// served ambient's trait tables), a written trait impl and an
    /// inherent impl (instances and methods continuing the ambient's id
    /// spaces), and calls into ambient functions and traits.
    const USER: &str =
        "#[derive(show, hash)]\nstruct point { x: int, y: int }\n\nenum tone \
         {\nwarm\ncool\n}\n\ntrait local { fn m(self) -> int }\n\nimpl local for tone {\nfn \
         m(self) -> int { 3 }\n}\n\nimpl point {\nfn norm(self) -> int { (self.x * self.x + \
         self.y * self.y) }\n}\n\nstruct wrap { v: json }\n\nfn main() -> () {\nconst p = point { \
         x: 3, y: 4 }\nconst t = warm\nconst w = wrap { v: json_null }\nconst j = \
         parse_json(\"[1,{\\\"k\\\":true}]\")\nif j is parse_err {\nprintln(\"bad\")\n} else \
         {\nprintln(\"${to_json(j)}\")\n}\nprintln(\"${p.show()} ${p.norm()} ${t.m()} ${max(1, \
         2)}\")\n}\n";

    /// The embedded artifact must byte-match a fresh generation over the
    /// current source: any grammar, checker, resolution, effects, or
    /// format drift fails here until `cargo run -p ds-stdlib --example
    /// gen-ambient-dsi` regenerates it.
    #[test]
    fn the_artifact_matches_a_fresh_generation() {
        let fresh = artifact_bytes(
            ds_mod::Hash128::compute(crate::AMBIENT_SOURCE.as_bytes()),
            &super::generate(),
        );
        assert_eq!(
            DSI[..HEADER],
            ds_mod::Hash128::compute(crate::AMBIENT_SOURCE.as_bytes()).as_bytes()[..],
            "the artifact's source hash drifted"
        );
        assert_eq!(
            &DSI[HEADER..],
            &fresh[HEADER..],
            "the checked-ambient artifact drifted; regenerate with `cargo run -p ds-stdlib \
             --example gen-ambient-dsi`"
        );
    }

    /// The served analyze answers the same bundle as the fresh analyze
    /// over the same ambient-plus-user program: identical trees,
    /// diagnostics, namespace, resolutions, universe mint sequence,
    /// plain declaration tables, instance environment, solved span-keyed
    /// records, and checked facts (the raw solved-handle comparisons are
    /// exact because the two runs mint identical sequences — the pin
    /// this gate enforces, failing loudly rather than drifting, should
    /// the artifact's log ever stop capturing the sequence).
    #[test]
    fn the_served_analyze_matches_a_fresh_analyze() {
        let mut files = ds_diag::Files::new();
        let ambient = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let user = files.add_source("user.ds", USER);
        let user_ast = ds_parse::parse_script(&files, user).expect("the user source parses");

        // The served path: the blob tree first (pre-expanded), the
        // artifact's tables beside it.
        let served_tree = crate::ambient_ast(ambient).expect("the AST blob verifies");
        let served = super::ambient_dsi(ambient).expect("the artifact verifies");
        let served_run = ds_meta::analyze_served(
            &files,
            vec![served_tree, std::sync::Arc::new(user_ast.clone())],
            &[true, false],
            served.package,
            served.resolutions,
            served.decls,
        );
        assert!(
            served_run.checked.diags.is_empty(),
            "the served run must check clean: {:?}",
            served_run.checked.diags
        );

        // The fresh path over the same sources.
        let fresh_tree = ds_parse::parse(&files, ambient).expect("the ambient parses");
        let fresh_run = ds_meta::analyze_owned(
            &files,
            vec![
                std::sync::Arc::new(fresh_tree),
                std::sync::Arc::new(user_ast),
            ],
            &[false, false],
        );
        assert!(
            fresh_run.checked.diags.is_empty(),
            "the fresh run must check clean: {:?}",
            fresh_run.checked.diags
        );

        assert_eq!(
            served_run.checked.diags, fresh_run.checked.diags,
            "both runs check the same program clean"
        );
        for (served_tree, fresh_tree) in served_run.asts.iter().zip(fresh_run.asts.iter()) {
            let served_bytes = postcard::to_allocvec(served_tree.as_ref()).expect("serializes");
            let fresh_bytes = postcard::to_allocvec(fresh_tree.as_ref()).expect("serializes");
            assert_eq!(
                served_bytes, fresh_bytes,
                "the trees must answer identically"
            );
        }
        assert_eq!(
            served_run.package, fresh_run.package,
            "the namespaces must match"
        );
        assert_eq!(
            served_run.resolutions[..],
            fresh_run.resolutions[..],
            "the resolutions must match"
        );
        assert_eq!(
            gates::mint_facts(&served_run.decls.universe),
            gates::mint_facts(&fresh_run.decls.universe),
            "the universe mint sequences must match"
        );
        assert_eq!(
            gates::plain_tables(&served_run),
            gates::plain_tables(&fresh_run),
            "the plain declaration tables must match"
        );
        assert_eq!(
            gates::signature_tables(&served_run),
            gates::signature_tables(&fresh_run),
            "the signature tables must match"
        );
        assert_eq!(
            gates::instance_rows(&served_run),
            gates::instance_rows(&fresh_run),
            "the instance rows must match"
        );
        assert_eq!(
            gates::const_rows(&served_run),
            gates::const_rows(&fresh_run),
            "the top-level binding rows must match (the served base and the fresh clones)"
        );
        assert_ne!(gates::const_rows(&served_run), Vec::new());

        // The serve must actually install its prefix: a marker regression
        // would rebuild everything fresh over the served tables and still
        // answer identically, so the pins trip it here.
        assert!(
            served_run.decls.served_defs > 0
                && served_run.decls.served_methods > 0
                && served_run.decls.instances.served_len() > 0,
            "the artifact's prefix must arrive served, not rebuilt"
        );

        assert_eq!(
            gates::trait_facts(&served_run),
            gates::trait_facts(&fresh_run),
            "the trait registries must match"
        );

        // The solved span-keyed records (raw handles, same mint
        // sequences).
        assert_eq!(
            served_run.decls.trait_impl_args, fresh_run.decls.trait_impl_args,
            "the trait-reference arguments must match"
        );
        assert_eq!(
            served_run.decls.inherent_impl_bounds, fresh_run.decls.inherent_impl_bounds,
            "the inherent bounds must match"
        );
        assert_eq!(
            served_run.decls.impl_fn_rets, fresh_run.decls.impl_fn_rets,
            "the impl-member returns must match"
        );

        // The checked facts: top-level types raw, per-expression facts
        // rendered (Val carries no equality).
        assert_eq!(
            served_run.checked.def_types, fresh_run.checked.def_types,
            "the top-level types must match"
        );
        assert_eq!(
            gates::rendered_exprs(&served_run),
            gates::rendered_exprs(&fresh_run),
            "the checked expression facts must match"
        );

        // The effects: the served pass (user-only walk over the served
        // rows) must equal the fresh whole-package pass.
        let served_effects = ds_check::effects::effects_of_resolved_served(
            &served_run.asts[1..],
            &served_run.package,
            &served_run.resolutions[1..],
            &served_run.checked.hole_show_dispatches,
            &served.effect_defs,
            &served.effect_methods,
            crate::declared_rows(),
            crate::world_caps(),
        );
        let fresh_effects = ds_check::effects::effects_of_resolved(
            &fresh_run.asts[..],
            &fresh_run.package,
            &fresh_run.resolutions[..],
            &fresh_run.checked.hole_show_dispatches,
            crate::declared_rows(),
            crate::world_caps(),
        );
        assert_eq!(
            served_effects.defs(),
            fresh_effects.defs(),
            "the served effect rows must match the fresh pass"
        );
    }

    /// A file id the artifact was not generated under is a cache miss,
    /// never a serve.
    #[test]
    fn a_foreign_file_id_falls_back() {
        let Err(error) = super::ambient_dsi(ds_diag::FileId::new(9)) else {
            panic!("the artifact addresses its own file")
        };
        assert!(matches!(error, PrefixDsiError::FileMismatch));
    }

    /// Every serve of the decoded artifact installs the same shared
    /// tables: the postcard decode and conversion run once per process,
    /// so every member compile binds the ambient the first did — the
    /// namespace and resolutions answer equal, and the solved effect
    /// rows answer as one shared handle (a rebuilt row set would compare
    /// equal too, so the share is pinned by identity).
    #[test]
    fn every_serve_answers_the_same_tables() {
        let mut files = ds_diag::Files::new();
        let file = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let first = super::ambient_dsi(file).expect("the artifact verifies");
        let second = super::ambient_dsi(file).expect("the memoized decode serves");
        assert_eq!(
            first.package, second.package,
            "the rebuilt namespace answers the first serve's"
        );
        assert_eq!(
            first.resolutions, second.resolutions,
            "the rebuilt resolutions answer the first serve's"
        );
        assert!(
            std::sync::Arc::ptr_eq(&first.effect_defs, &second.effect_defs),
            "the solved effect rows are one shared handle across serves"
        );
        assert!(
            std::sync::Arc::ptr_eq(&first.effect_methods, &second.effect_methods),
            "the solved method rows are one shared handle across serves"
        );
    }

    /// A user program colliding with the served ambient keeps the fresh
    /// path's diagnostics: a redeclared ambient name still reports the
    /// duplicate at collection, and a user impl whose head overlaps a
    /// served instance still hits the fresh coherence path — its
    /// declaration probes against the installed served rows, and the
    /// closure pass keeps every pair a fresh row takes part in.
    #[test]
    fn a_user_collision_with_the_served_ambient_still_diagnoses() {
        const COLLIDE: &str = "fn println(msg: string) -> () { }\n\nimpl show for int {\nfn \
                               show(self) -> string { \"i\" }\n}\n";
        let mut files = ds_diag::Files::new();
        let ambient = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let user = files.add_source("collide.ds", COLLIDE);
        let user_ast = ds_parse::parse_script(&files, user).expect("the user source parses");

        let served_tree = crate::ambient_ast(ambient).expect("the AST blob verifies");
        let served = super::ambient_dsi(ambient).expect("the artifact verifies");
        let served_run = ds_meta::analyze_served(
            &files,
            vec![served_tree, std::sync::Arc::new(user_ast.clone())],
            &[true, false],
            served.package,
            served.resolutions,
            served.decls,
        );
        assert!(
            !served_run.checked.diags.is_empty(),
            "the collision must diagnose"
        );

        let fresh_tree = ds_parse::parse(&files, ambient).expect("the ambient parses");
        let fresh_run = ds_meta::analyze_owned(
            &files,
            vec![
                std::sync::Arc::new(fresh_tree),
                std::sync::Arc::new(user_ast),
            ],
            &[false, false],
        );
        assert_eq!(
            served_run.checked.diags, fresh_run.checked.diags,
            "the served run answers the fresh run's collision diagnostics"
        );
        assert!(
            served_run
                .checked
                .diags
                .iter()
                .any(|diag| diag.code == ds_diag::ErrorCode::DuplicateDefinition),
            "the redeclared ambient name reports the duplicate"
        );
        assert!(
            served_run
                .checked
                .diags
                .iter()
                .any(|diag| diag.code == ds_diag::ErrorCode::InstanceOverlap),
            "the overlapping user impl hits the coherence path"
        );
    }
}
